    cir_result: 'Recommandé pour vous', cir_engine_cpu: 'Tourne sur le processeur', cir_engine_gpu: 'Tourne sur la carte graphique ({e})', cir_engine_metal: 'Tourne sur le GPU Apple (Metal)',
